// Mock Linear escalation issues - swap for the Linear GraphQL API filtered to support-escalation label
return [{ json: { issues: [
  { issue: 'ENG-451', title: 'Workflow crashes on large payloads', state: 'In Progress', daysSinceUpdate: 6, linkedTickets: 4, arrImpact: 240000, cycle: 'current' },
  { issue: 'ENG-460', title: 'Webhook dedupe race condition', state: 'Todo', daysSinceUpdate: 12, linkedTickets: 2, arrImpact: 96000, cycle: 'none' },
  { issue: 'ENG-455', title: 'OAuth refresh fails for legacy apps', state: 'In Review', daysSinceUpdate: 1, linkedTickets: 7, arrImpact: 310000, cycle: 'current' },
  { issue: 'ENG-441', title: 'Editor freeze with 200+ nodes', state: 'Done', daysSinceUpdate: 2, linkedTickets: 3, arrImpact: 54000, cycle: 'current' }
] } }];

// Deterministic hygiene rules: no AI needed to know 12 days of silence is too many
const { issues } = $input.first().json;
const stale = issues.filter(i => i.state !== 'Done' && i.daysSinceUpdate > 5).sort((a, b) => b.arrImpact - a.arrImpact);
const uncycled = issues.filter(i => i.state !== 'Done' && i.cycle === 'none');
const shipping = issues.filter(i => i.state === 'Done' || i.state === 'In Review');
let body = 'Escalation hygiene, midweek sweep:

== Stale (5+ days without update, sorted by ARR at stake) ==
';
body += stale.length ? stale.map(i => i.issue + ' - ' + i.title + '
  ' + i.daysSinceUpdate + 'd silent | ' + i.linkedTickets + ' customer tickets | $' + (i.arrImpact/1000).toFixed(0) + 'K ARR
  Action: comment with customer impact + ask for an ETA we can give customers').join('
') : 'None.';
body += '

== Not in any cycle ==
';
body += uncycled.length ? uncycled.map(i => i.issue + ' - ' + i.title + ' ($' + (i.arrImpact/1000).toFixed(0) + 'K ARR waiting)
  Action: raise in the eng sync, escalations do not live in the backlog').join('
') : 'None.';
body += '

== Shipping or shipped (tell the customers!) ==
';
body += shipping.length ? shipping.map(i => i.issue + ' - ' + i.title + ' (' + i.state + ', ' + i.linkedTickets + ' tickets to update)').join('
') : 'None.';
body += '

Rule: an escalation without a current status is a promise we are quietly breaking.';
return [{ json: { subject: 'Escalation hygiene: ' + stale.length + ' stale, ' + uncycled.length + ' uncycled, ' + shipping.length + ' to announce', body } }];
